final testModel = Model(
  id: 'gpt-4o-mini',
  name: 'GPT-4o mini',
  api: 'openai-completions',
  provider: 'openai',
  baseUrl: 'https://api.openai.com/v1',
  input: const ['text'],
  contextWindow: 128000,
  maxTokens: 16384,
  cost: const ModelCost(input: 0.15, output: 0.6, cacheRead: 0.075),
);

void main() {
  test('PROBE: parallel same-name calls with standard empty-args openings',
      () async {
    final body = sseBody([
      {
        'choices': [
          {
            'delta': {
              'tool_calls': [
                {
                  'index': 0,
                  'id': 'call_a',
                  'type': 'function',
                  'function': {'name': 'bash', 'arguments': ''},
                },
              ],
            },
          },
        ],
      },
      {
        'choices': [
          {
            'delta': {
              'tool_calls': [
                {
                  'index': 1,
                  'id': 'call_b',
                  'type': 'function',
                  'function': {'name': 'bash', 'arguments': ''},
                },
              ],
            },
          },
        ],
      },
      {
        'choices': [
          {
            'delta': {
              'tool_calls': [
                {
                  'index': 0,
                  'function': {'arguments': '{"command":"ls"}'},
                },
              ],
            },
          },
        ],
      },
      {
        'choices': [
          {
            'delta': {
              'tool_calls': [
                {
                  'index': 1,
                  'function': {'arguments': '{"command":"pwd"}'},
                },
              ],
            },
          },
        ],
      },
      {
        'choices': [
          {'delta': <String, dynamic>{}, 'finish_reason': 'tool_calls'},
        ],
      },
      'data: [DONE]\n\n',
    ]);

    final stream = streamOpenAICompletions(
      testModel,
      Context(messages: [UserMessage.text('hi', timestamp: DateTime.utc(2026))]),
      const OpenAICompletionsOptions(apiKey: 'test'),
      sseClient(body),
    );
    final events = await stream.toList();
    final starts = events.whereType<ToolCallStartEvent>().toList();
    final ends = events.whereType<ToolCallEndEvent>().toList();
    // ignore: avoid_print
    print('starts=${starts.length}');
    for (final e in ends) {
      // ignore: avoid_print
      print('end id=${e.toolCall.id} name=${e.toolCall.name} args=${e.toolCall.arguments}');
    }
    expect(starts, hasLength(2), reason: 'clean relay: two ToolCallStartEvents');
    expect(ends[0].toolCall.id, 'call_a');
    expect(ends[1].toolCall.id, 'call_b', reason: 'clean relay: id preserved');
    expect(ends[1].toolCall.name, 'bash', reason: 'clean relay: name preserved');
    expect(ends[1].toolCall.arguments, {'command': 'pwd'});
  });
}
